import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.DTisvaUJ.js";const p=JSON.parse('{"title":"Azure Translator 설정","description":"Mutelink의 클라우드 번역을 위한 Azure Translator 설정입니다. 리소스 생성, 무료 요금제, 키와 지역을 안내합니다.","frontmatter":{"description":"Mutelink의 클라우드 번역을 위한 Azure Translator 설정입니다. 리소스 생성, 무료 요금제, 키와 지역을 안내합니다.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/azure-translator"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:title","content":"Azure Translator 설정 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink의 클라우드 번역을 위한 Azure Translator 설정입니다. 리소스 생성, 무료 요금제, 키와 지역을 안내합니다."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/ko/guide/azure-translator"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Azure Translator 설정 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink의 클라우드 번역을 위한 Azure Translator 설정입니다. 리소스 생성, 무료 요금제, 키와 지역을 안내합니다."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}]]},"headers":[],"relativePath":"ko/guide/azure-translator.md","filePath":"ko/guide/azure-translator.md"}'),l={name:"ko/guide/azure-translator.md"};function n(i,t,s,u,d,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="azure-translatorの導入" tabindex="-1">Azure Translator 설정 <a class="header-anchor" href="#azure-translatorの導入" aria-label="Permalink to &quot;Azure Translator 설정 {#azure-translatorの導入}&quot;">​</a></h1><p>Microsoft 클라우드 번역인 Azure Translator를 Mutelink에서 쓰기 위한 키 생성 방법입니다. F0 무료 요금제는 월 200만 자까지 제공합니다.</p><p>PC에서 작동하는 PLaMo와 TranslateGemma에는 이 준비가 필요 없습니다. <a href="/Mutelink-releases/ko/compare/translation">번역 엔진 비교</a>를 참고하세요.</p><div class="info custom-block"><p class="custom-block-title">시작 전 안내</p><ul><li>Azure 등록에는 주소, 전화번호, 신용카드 인증이 필요합니다. 등록과 인증을 마친 <strong>종량제 구독</strong>을 준비해야 하며, Microsoft 계정 가입만으로는 완료되지 않습니다.</li><li>F0 무료 요금제에서는 월 200만 자를 넘어도 요금이 부과되지 않고 그달의 번역이 중단됩니다.</li><li>번역할 글은 Microsoft 서버로 전송됩니다(<a href="/Mutelink-releases/ko/about/privacy">개인정보</a>).</li><li>Azure 포털 화면과 용어는 바뀔 수 있습니다. 안내와 다르면 비슷한 이름의 항목을 찾으세요.</li></ul></div><h2 id="_1-azureの従量課金制サブスクリプションを用意する" tabindex="-1">1. Azure 종량제 구독 준비 <a class="header-anchor" href="#_1-azureの従量課金制サブスクリプションを用意する" aria-label="Permalink to &quot;1. Azure 종량제 구독 준비 {#_1-azureの従量課金制サブスクリプションを用意する}&quot;">​</a></h2><ol><li><a href="https://azure.microsoft.com/ja-jp/pricing/purchase-options/azure-account" target="_blank" rel="noreferrer">Azure 계정 등록 페이지</a>에서 종량제 등록을 시작합니다.</li><li>Microsoft 계정으로 로그인하거나 계정을 만드세요.</li><li>주소 등 등록 정보를 입력하고 전화번호·신용카드 인증과 결제 수단 등록을 마칩니다.</li><li><a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azure 포털</a>의 구독에서 종량제 구독이 생성되고 활성 상태인지 확인합니다.</li><li>무료 계정으로 시작했다면 필요한 경우 업그레이드에서 종량제로 전환하세요.</li></ol><p>이미 활성 종량제 구독이 있다면 이 단계는 필요 없습니다.</p><p>Azure 종량제와 Translator 리소스의 가격 책정 계층은 별개입니다. 다음 단계에서는 <strong>Free F0</strong>를 선택합니다. 다른 유료 서비스나 Translator 유료 계층을 사용하면 요금이 발생합니다.</p><h2 id="_2-translatorのリソースを作る" tabindex="-1">2. Translator 리소스 생성 <a class="header-anchor" href="#_2-translatorのリソースを作る" aria-label="Permalink to &quot;2. Translator 리소스 생성 {#_2-translatorのリソースを作る}&quot;">​</a></h2><ol><li><a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azure 포털</a>을 엽니다.</li><li>위 검색창에서 Translator를 찾아 선택하고 만들기를 누르세요(일본어 UI에서는 翻訳ツール).</li><li>다음과 같이 입력합니다.</li></ol><table tabindex="0"><thead><tr><th>항목</th><th>입력할 내용</th></tr></thead><tbody><tr><td>구독</td><td>본인 구독(하나뿐이면 그대로)</td></tr><tr><td>리소스 그룹</td><td>새로 만들기를 눌러 원하는 이름 입력(예: <code>mutelink</code>)</td></tr><tr><td>지역</td><td>가까운 지역(예: <code>Japan East</code>). <strong>나중에 이 지역을 Mutelink에 입력합니다</strong></td></tr><tr><td>이름</td><td>리소스 식별 이름(예: <code>mutelink-translator-1234</code>). 이미 사용 중이면 끝의 숫자 등을 바꾸세요</td></tr><tr><td>가격 책정 계층</td><td><strong>Free F0</strong>(월 200만 자 무료)</td></tr></tbody></table><ol start="4"><li>검토 + 만들기를 누르고 내용을 확인한 다음 만들기를 누릅니다.</li><li>배포가 완료되면 리소스로 이동을 누릅니다.</li></ol><p>리소스로 이동을 누르면 Translator 대신 리소스 그룹이 열릴 수 있습니다. 목록에서 만든 Translator를 선택하세요. 바로 보이지 않으면 새로 고침을 누른 뒤 표시된 Translator 이름을 클릭하세요.</p><div class="tip custom-block"><p class="custom-block-title">Free F0를 선택할 수 없을 때</p><p>구독 하나당 무료 Translator 리소스는 하나만 만들 수 있습니다. 이전에 만든 리소스가 남아 있는지 확인하세요.</p></div><h2 id="_3-キーとリージョンを確認する" tabindex="-1">3. 키와 지역 확인 <a class="header-anchor" href="#_3-キーとリージョンを確認する" aria-label="Permalink to &quot;3. 키와 지역 확인 {#_3-キーとリージョンを確認する}&quot;">​</a></h2><ol><li>Translator 화면의 왼쪽 메뉴에서 키 및 엔드포인트를 엽니다. 리소스 그룹에 있다면 먼저 목록의 Translator를 클릭하세요.</li><li>키 1(KEY 1)을 복사합니다.</li><li>위치/지역(Location/Region)의 값(예: <code>japaneast</code>)을 적어 둡니다.</li></ol><div class="warning custom-block"><p class="custom-block-title">키를 다른 사람에게 보여 주지 마세요</p><p>키를 알면 누구나 본인 할당량으로 번역할 수 있습니다. 방송·화면 공유·스크린샷에 노출하지 마세요. 유출되면 같은 화면에서 키 1을 다시 생성하세요.</p></div><h2 id="_4-mutelinkに入れる" tabindex="-1">4. Mutelink에 입력 <a class="header-anchor" href="#_4-mutelinkに入れる" aria-label="Permalink to &quot;4. Mutelink에 입력 {#_4-mutelinkに入れる}&quot;">​</a></h2><ol><li>Mutelink 설정 &gt; 번역을 엽니다.</li><li>Azure Translator 항목의 키에 키 1을, 지역에 적어 둔 값(예: <code>japaneast</code>)을 입력하세요.</li><li>번역 테스트에서 번역 결과가 나오는지 확인합니다.</li><li>번역 엔진 우선순위에서 Azure Translator를 원하는 순서에 놓으세요.</li></ol><p>키는 이 PC의 설정에만 저장됩니다.</p><h2 id="うまくいかないとき" tabindex="-1">문제 해결 <a class="header-anchor" href="#うまくいかないとき" aria-label="Permalink to &quot;문제 해결 {#うまくいかないとき}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>상황</th><th>확인할 내용</th></tr></thead><tbody><tr><td>테스트에서 키 오류</td><td>앞뒤 공백 또는 Translator가 아닌 다른 리소스의 키인지 확인</td></tr><tr><td>테스트에서 지역 오류</td><td>위치/지역의 값을 그대로 입력했는지 확인(<code>Japan East</code>가 아닌 <code>japaneast</code>)</td></tr><tr><td>잘 되다가 갑자기 실패</td><td>월 200만 자를 다 썼는지 Azure 리소스의 메트릭에서 확인</td></tr><tr><td>생성 직후 실패</td><td>사용할 수 있을 때까지 몇 분 걸릴 수 있음</td></tr></tbody></table><p>설정 &gt; 번역에는 이 PC의 앱이 번역한 이번 달·오늘·최근 30일의 글자 수가 표시됩니다. 같은 키를 다른 곳에서 쓴 양은 포함하지 않습니다.</p><h2 id="やめるとき" tabindex="-1">사용을 중단할 때 <a class="header-anchor" href="#やめるとき" aria-label="Permalink to &quot;사용을 중단할 때 {#やめるとき}&quot;">​</a></h2><p>Azure 포털에서 만든 리소스 또는 리소스 그룹을 삭제하고 Mutelink 설정 &gt; 번역의 키도 지우세요.</p><p>등록 조건과 가격 계층은 Microsoft의 <a href="https://azure.microsoft.com/ja-jp/pricing/purchase-options/azure-account" target="_blank" rel="noreferrer">Azure 계정 안내</a>와 <a href="https://learn.microsoft.com/ja-jp/azure/ai-services/translator/how-to/create-translator-resource" target="_blank" rel="noreferrer">Translator 리소스 만들기</a>를 확인하세요.</p>',26)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
